        {"t": _hr + 60, "m": "A", "w": "local", "n": 1, "i": 7, "c": 3, "ri": 7, "o": 1, "d": 9},
        {"t": _hr + 120, "m": "A", "w": "local", "n": 1, "i": 5, "o": 1, "x": 1, "d": 1},
        {"t": _hr + 180, "m": "B", "w": "claude", "n": 1, "i": 4, "o": 1},
        {"t": _hr + 200, "m": "A", "a": 1},
