class _SayP26:
    def __init__(self, args, **k):
        self.args, self.pid, self._rc, self.waited = args, 4242, None, 0
        self.done = _th26.Event()
        _spawned26.append(self)

    def poll(self):
        return self._rc

    def wait(self, timeout=None):
        self.waited += 1
        self.done.wait(timeout)
        self._rc = 0
        return 0

    def terminate(self):
        _killed26.append("term")
        self.done.set()


