_so["mode"] = "missing"
_so_missing_found = _so["ssh_run"]({"host": "h"}, "x")
_so["shutil"] = _t17.SimpleNamespace(which=lambda n: None)
_so_missing = _so["ssh_run"]({"host": "h"}, "x")
_so_calls.clear()
_so["mode"] = "resolve"
