def _kat7(mod, name, fn):
    """cai_crypto's verdict with one libsodium call replaced."""
    _orig = getattr(mod, name)
    setattr(mod, name, fn)
    _cc7.reset()
    try:
        return _cc7.status()
    finally:
        setattr(mod, name, _orig)
        _cc7.reset()


