def _ann_profiles(seg_src):
    _pn, _pd, _root = _pm8(None, hooks=frozenset({"profiles"}))
    _pn.update(base64=__import__("base64"), EXPORT_DIRNAME="exports", NotLanded=_pn["StaleProfile"],
               stage_path=None, drop_run_file=None)
    exec(seg_src, _pn)
