def _l7_get():
    return _svq("/api/servers/models?id=" + _sid34)[1]


def _l7_wait(secs=20):
    end = time.time() + secs
    g = _l7_get()
    while time.time() < end and g.get("running"):
        time.sleep(0.3)
        g = _l7_get()
    return g


