        _jsfn(src, "function lsKeys(){"), _jsfn(src, "function prefVal(k,v){"),
        _jsfn(src, "async function storeBoot(){"),
        _jsfn(src, "function micWarmOn(){"), _jsfn(src, "function setMicWarm(on){"),
        _jsfn(src, "function micWarmPaint(){"),
