    js = _MW_JS.replace("async function api(u,o){", "var api=async function(u,o){", 1).replace(
        "return{ok:true,json:async()=>({})};}\nconst localStorage", "return{ok:true,json:async()=>({})};};\nconst localStorage", 1)
