def _g56_run(src):
    out = []
    for name, fn in _G56_CHECKS:
        try:
            ok, det = fn(src)
        except Exception as exc:
            ok, det = False, "%s: %s" % (type(exc).__name__, exc)
        out.append((name, ok, det))
    return out


