def _b41_run(src, which=None):
    out = []
    for i, (name, fn) in enumerate(_B41_CHECKS):
        if which is not None and i not in which:
            continue
        try:
            ok, det = fn(src)
        except Exception as e_:
            ok, det = False, "raised %r" % (e_,)
        out.append((i, name, bool(ok), det))
    return out

